from pathlib import Path
import hashlib,json,os,shutil,subprocess,time
root=Path("/tmp/macro-ivspread11080-proof-20261111")
py=str(root/"native-env/bin/python")
env={**os.environ,"MM_DATA_GUARD":"1","PYTHONDONTWRITEBYTECODE":"1","RENDER_NO_DRIP":"1"}
receipts={}
for variant in ["after","before"]:
 if variant=="before":
  shutil.copyfile(root/"after/tests/test_options_ivspread.py",root/"before/tests/test_options_ivspread.py")
 cmd=[py,"-m","pytest","tests/test_options_skew.py","tests/test_options_ivspread.py","-q","-p","no:cacheprovider","--junitxml="+str(root/(variant+"-owner.xml"))]
 start=time.monotonic();p=subprocess.run(cmd,cwd=root/variant,env=env,capture_output=True,timeout=240)
 raw=p.stdout+p.stderr;log=root/(variant+"-owner-final.log");log.write_bytes(raw)
 rec={"variant":variant,"command":cmd,"returncode":p.returncode,"seconds":round(time.monotonic()-start,3),"log_bytes":len(raw),"log_sha256":hashlib.sha256(raw).hexdigest(),"summary":[x for x in raw.decode().splitlines() if x.startswith("FAILED ") or (" passed" in x and not "warning" in x)]}
 receipts[variant]=rec;(root/"final-owner-red-green.json").write_text(json.dumps(receipts,indent=2)+"\n")
 print(json.dumps(rec),flush=True)
 if variant=="after" and p.returncode:
  print(raw.decode()[-7000:],flush=True)
  raise SystemExit("Candidate not green; original source falsifier not run")
print(json.dumps({"complete":True,"after_exit":receipts["after"]["returncode"],"before_exit":receipts["before"]["returncode"]}),flush=True)
